// 2. Validate Input
// Confirms the notification payload handed off by WF-07 has what this
// workflow needs to resolve a chat and send a Telegram message.

const item = $input.first().json;

const incidentId = item.incidentId;
const destination = item.destination || {};
const chatIdKey = destination.chatId;
const assignedTeam = destination.team;
const priority = item.priority;

const missing = [];
if (!incidentId) missing.push('incidentId');
if (!chatIdKey) missing.push('destination.chatId');
if (!assignedTeam) missing.push('destination.team');
if (!priority) missing.push('priority');

return [{
  json: {
    isValid: missing.length === 0,
    missingFields: missing,
    ...item
  }
}];

// 3. Resolve Telegram Chat ID
// WF-07 already decided WHICH team a notification belongs to and handed
// off a placeholder chat-id key (e.g. TELEGRAM_CHAT_TRANSMISSION_TEAM).
// This node turns that key into the REAL Telegram chat ID using the
// table below -- the same inline-mapping pattern WF-07 already uses for
// its own team -> key lookup, chosen because this n8n instance blocks
// $env access from Code nodes.
//
// REPLACE each value below with your real Telegram chat/group ID --
// see the Telegram Setup Guide. Unmapped or not-yet-configured keys
// fall back to the NOC chat rather than being undeliverable.

const item = $input.first().json;

const destination = item.destination || {};
const chatIdKey = destination.chatId;

const CHAT_ID_TABLE = {
  'TELEGRAM_CHAT_TRANSMISSION_TEAM': '1239214407',
  'TELEGRAM_CHAT_POWER_TEAM': '1239214407',
  'TELEGRAM_CHAT_ACCESS_NETWORK_TEAM': '1239214407',
  'TELEGRAM_CHAT_IP_NETWORK_TEAM': '1239214407',
  'TELEGRAM_CHAT_IP_CORE_TEAM': '1239214407',
  'TELEGRAM_CHAT_TRANSMISSION_MONITORING': '1239214407',
  'TELEGRAM_CHAT_SITE_MAINTENANCE_TEAM': '1239214407',
  'TELEGRAM_CHAT_NOC': '1239214407'
};

const directValue = chatIdKey ? CHAT_ID_TABLE[chatIdKey] : undefined;
const fallbackValue = CHAT_ID_TABLE['TELEGRAM_CHAT_NOC'];
const resolvedChatId = directValue || fallbackValue || null;
const chatIdFallbackUsed = !directValue;

return [{
  json: {
    ...item,
    chatIdKey,
    resolvedChatId,
    chatIdFallbackUsed
  }
}];

// 4. Format Telegram Message
// Builds the Telegram message text. The header emoji/label is derived
// from priority (and boosted for immediateEscalation) rather than
// hardcoded to 'Critical', since this workflow handles every priority
// level, not just Critical incidents. Fields not yet passed through the
// pipeline (alarmType, region, customerImpact, aiRecommendation) default
// gracefully -- see README 'Note on incomplete field passthrough from
// WF-07'.

const item = $input.first().json;

const PRIORITY_EMOJI = { Critical: '\uD83D\uDEA8', Major: '\u26A0\uFE0F', Minor: '\uD83D\uDD37', Warning: '\u2139\uFE0F' };
const emoji = PRIORITY_EMOJI[item.priority] || '\uD83D\uDD14';
const headerPrefix = item.immediateEscalation === true ? (emoji + ' IMMEDIATE ESCALATION - ') : (emoji + ' ');
const header = headerPrefix + (item.priority || 'Unknown') + ' Fiber Alarm';

const incidentId = item.incidentId || 'Unknown';
const site = item.siteId || item.site || 'Not specified';
const region = item.region || 'Not specified';
const alarmType = item.alarmType || item.rawAlarmType || 'Not specified';
const priority = item.priority || 'Not specified';
const assignedTeam = (item.destination && item.destination.team) || 'Not specified';
const sla = item.slaDeadline ? ('By ' + item.slaDeadline) : 'Not set';
const businessImpact = item.businessImpact || 'Not available';
const customerImpact = item.customerImpact || (typeof item.affectedCustomers === 'number' ? (item.affectedCustomers + ' customer(s) affected') : 'Not available');
const aiRecommendation = item.aiRecommendation || 'Not available';
const time = item.preparedAt || new Date().toISOString();

const messageText =
  header + '\n\n' +
  'Incident ID: ' + incidentId + '\n' +
  'Site: ' + site + '\n' +
  'Region: ' + region + '\n' +
  'Alarm: ' + alarmType + '\n' +
  'Priority: ' + priority + '\n' +
  'Assigned Team: ' + assignedTeam + '\n' +
  'SLA: ' + sla + '\n' +
  'Business Impact: ' + businessImpact + '\n' +
  'Customer Impact: ' + customerImpact + '\n' +
  'AI Recommendation: ' + aiRecommendation + '\n' +
  'Time: ' + time;

return [{
  json: {
    ...item,
    messageText
  }
}];

// 7. Build Failure Record
// Runs on the Telegram send node's error output (after all 3 retry
// attempts have been exhausted). Assembles a structured failure record
// combining the original message context with the Telegram API's error.
// n8n's Telegram node puts the error directly on item.error as a STRING
// (e.g. 'Bad Request: chat not found'), not an { message } object -- this
// handles both shapes defensively.

const item = $input.first().json;
const source = $('4. Format Telegram Message').item.json;

let errorMessage = 'Unknown Telegram delivery error';
if (typeof item.error === 'string' && item.error) {
  errorMessage = item.error;
} else if (item.error && item.error.message) {
  errorMessage = item.error.message;
} else if (item.message) {
  errorMessage = item.message;
}

return [{
  json: {
    status: 'failed',
    incidentId: source.incidentId,
    chatId: source.resolvedChatId,
    assignedTeam: (source.destination && source.destination.team) || null,
    errorMessage,
    attemptsMade: 3,
    failedAt: new Date().toISOString()
  }
}];
